def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    encrypted = ''

    for char in s:
        if char.isalpha():
            index = (alphabet.index(char) + 2) % 26
            encrypted += alphabet[index]

    return encrypted

