def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    rotated_alphabet = alphabet[2:] + alphabet[:2]
    mapping = str.maketrans(alphabet, rotated_alphabet)
    return s.translate(mapping)

